"""Write the generated C tables (gfx.h, gfx.c) for the game."""

MODES = {"static": "ANIM_STATIC", "loop": "ANIM_LOOP", "once": "ANIM_ONCE"}

HEADER = """\
/* Generated by tools/gfxconv.py from texture2.bmp and FixitFelixJr.exe. Do not edit.

   Metasprites: msprites[rect] lists the 16x16 parts of sheet rect `rect`, positioned
   relative to the rect's top-left corner (playfield orientation). spr_parts[first ..
   first+overlay-1] are the Super Felix hammer overlay, spr_parts[first+overlay ..
   first+overlay+count-1] the picture itself. A part is laid out like bytes 0-3 of a
   sprite RAM entry: dx, dy, code bits 7:0, attr (code bits 9:8 | palette << 3).
   w8/h8 are the rect size in 8-pixel units. Rects drawn as tilemaps instead
   (TM_SCENERY and friends) have no parts.

   Super Felix: sprite palettes 0 .. SPR_PAL_CYCLE_END-1 are CYCLE groups of 5:
   group base g*5 is the normal colours, g*5+f (f = 1..4) recolours Felix's clothes
   like the original felix1..4 textures. For a part whose palette is below
   SPR_PAL_CYCLE_END add f to the palette (attr += f << 3). Hammer overlay parts are
   drawn on top only when h != 0, with palette SPR_PAL_HAMMER + h - 1 (attr +=
   (h - 1) << 3): red, green, white, cyan like hammer0..3. super_cycle[] holds the
   (f, h) pairs the original visits, f in bits 3:0 and h in bits 7:4, one step
   every 4 frames while Super Felix is active; f = h = 0 otherwise.

   Big sprites: rects BIG_RECT_FIRST .. BIG_RECT_FIRST+BIG_RECT_COUNT-1 are drawn with
   sprites of 16, 32 or 64 px instead of metasprites. big_pics[rect - BIG_RECT_FIRST]
   lists big_parts[first .. first+count-1]: dx, dy from the rect's top-left corner,
   code bits 7:0, attr (code bits 9:8 | palette << 3) and the sprite size byte
   (width, height, code bit 10; the game adds X bit 8 and the behind-BG bit).

   Tilemaps: entries are tile code | palette << 11, row-major, w x h tiles.
   The font is FONT_ENTRY(ch, colour) for ch 0x20-0x5F, colour 0-6. */
"""


def c_name(name):
    return name.lower()


def array(values, per_line=16):
    lines = []
    for i in range(0, len(values), per_line):
        lines.append("    " + ", ".join(values[i:i + per_line]) + ",")
    return "\n".join(lines)


def header(tables, gfx):
    layout = gfx["layout"]
    groups = layout["cycle_groups"]
    lines = [HEADER, "#ifndef FELIX_GFX_H", "#define FELIX_GFX_H", "", "#include <stdint.h>", ""]
    defines = [
        ("RECT_COUNT", len(tables["rects"])),
        ("ANIM_COUNT", len(tables["anims"])),
        ("TILEMAP_COUNT", len(gfx["tilemaps"])),
        ("TILE_COUNT", layout["tile_count"]),
        ("CELL_COUNT", layout["cell_count"]),
        ("FONT_TILE", layout["font_tile"]),
        ("FONT_PAL", layout["font_pal"]),
        ("FONT_OPAQUE_TILE", layout["font_opaque_tile"]),
        ("SVC_PAL", layout["service_pal"]),
        ("SVC_SOLID_TILE", layout["service_solid"]),
        ("SVC_GRID_TILE", layout["service_grid"]),
        ("SPR_PAL_CYCLE_END", groups * (1 + layout["cycle_variants"])),
        ("SPR_PAL_HAMMER", layout["hammer_pal"]),
        ("SUPER_CYCLE_LEN", len(layout["super_cycle"])),
        ("MIRROR_NONE", 255),
        ("BIG_RECT_FIRST", gfx["big_first"]),
        ("BIG_RECT_COUNT", len(gfx["bigsprites"])),
    ]
    lines += [f"#define {name} {value}" for name, value in defines]
    lines += [
        "#define FONT_ENTRY(ch, colour) ((uint16_t)(FONT_TILE + (ch) - 0x20) | "
        "((uint16_t)(FONT_PAL + (colour)) << 11))",
        "#define FONT_OPAQUE_ENTRY(ch, colour) ((uint16_t)(FONT_OPAQUE_TILE + (ch) - 0x20) | "
        "((uint16_t)(FONT_PAL + (colour)) << 11))",
        "",
        "enum { ANIM_STATIC, ANIM_LOOP, ANIM_ONCE };",
        "",
        "enum {",
    ]
    lines += [f"    TM_{m['name']}," for m in gfx["tilemaps"]]
    lines += [
        "};",
        "",
        "typedef struct { uint8_t dx, dy, code, attr; } spr_part_t;",
        "typedef struct { uint16_t first; uint8_t count, overlay, w8, h8; } msprite_t;",
        "typedef struct { uint8_t rect, mirror, dur; int16_t hx, hy; } anim_frame_t;",
        "typedef struct { const anim_frame_t *frames; uint8_t count, mode; } anim_t;",
        "typedef struct { uint8_t w, h; const uint16_t *map; } tilemap_t;",
        "typedef struct { uint8_t dx, dy, code, attr, size; } big_part_t;",
        "typedef struct { uint8_t first, count; } big_pic_t;",
        "",
        "extern const spr_part_t spr_parts[];",
        "extern const msprite_t msprites[RECT_COUNT];",
        "extern const anim_t anims[ANIM_COUNT];",
        "extern const tilemap_t tilemaps[TILEMAP_COUNT];",
        "extern const uint8_t super_cycle[SUPER_CYCLE_LEN];",
        "extern const big_part_t big_parts[];",
        "extern const big_pic_t big_pics[BIG_RECT_COUNT];",
        "extern const uint8_t win_tm[4][5][4];",
        "",
        "#endif",
        "",
    ]
    return "\n".join(lines)


def part_values(part):
    dx, dy, code, pal = part
    if code >= 1024:
        raise ValueError(f"metasprite cell code {code} needs the size byte")
    return f"{{{dx},{dy},{code & 0xFF},{(code >> 8) | pal << 3}}}"


def source(tables, gfx):
    out = ['#include "gfx.h"', ""]
    parts, entries = [], []
    for m, rect in zip(gfx["metasprites"], tables["rects"]):
        size = f"{rect['w'] // 8},{rect['h'] // 8}"
        entries.append(f"{{{len(parts)},{len(m['parts'])},{len(m['overlay'])},{size}}}")
        parts += [part_values(p) for p in m["overlay"] + m["parts"]]
    out += ["const spr_part_t spr_parts[] = {", array(parts, 8), "};", ""]
    out += ["const msprite_t msprites[RECT_COUNT] = {", array(entries, 8), "};", ""]

    frames, anims = [], []
    for anim in tables["anims"]:
        anims.append(f"{{&anim_frames[{len(frames)}],{len(anim['frames'])},{MODES[anim['mode']]}}}")
        for f in anim["frames"]:
            mirror = 255 if f["mirror"] < 0 else f["mirror"]
            frames.append(f"{{{f['rect']},{mirror},{f['dur']},{f['x']},{f['y']}}}")
    out += ["static const anim_frame_t anim_frames[] = {", array(frames, 6), "};", ""]
    out += ["const anim_t anims[ANIM_COUNT] = {", array(anims, 4), "};", ""]

    maps = []
    for m in gfx["tilemaps"]:
        if m["map"] is None:
            maps.append(f"{{{m['w']},{m['h']},0}}")
            continue
        name = f"tm_{c_name(m['name'])}"
        out += [f"static const uint16_t {name}[] = {{",
                array([f"0x{e:04x}" for e in m["map"]], 12), "};", ""]
        maps.append(f"{{{m['w']},{m['h']},{name}}}")
    out += ["const tilemap_t tilemaps[TILEMAP_COUNT] = {", array(maps, 4), "};", ""]

    big_parts, big_pics = [], []
    for r in range(gfx["big_first"], gfx["big_first"] + len(gfx["bigsprites"])):
        parts = gfx["bigsprites"][str(r)]
        big_pics.append(f"{{{len(big_parts)},{len(parts)}}}")
        for dx, dy, code, pal, size in parts:
            big_parts.append(f"{{{dx},{dy},{code & 0xFF},{((code >> 8) & 3) | pal << 3},{size}}}")
    out += ["const big_part_t big_parts[] = {", array(big_parts, 6), "};", ""]
    out += ["const big_pic_t big_pics[BIG_RECT_COUNT] = {", array(big_pics, 8), "};", ""]

    cycle = [str(f | h << 4) for f, h in gfx["layout"]["super_cycle"]]
    out += ["const uint8_t super_cycle[SUPER_CYCLE_LEN] = {", array(cycle), "};", ""]

    out.append("const uint8_t win_tm[4][5][4] = {")
    for row in gfx["window_table"]:
        slots = ", ".join("{" + ", ".join(f"TM_{name}" for name in slot) + "}" for slot in row)
        out.append(f"    {{{slots}}},")
    out += ["};", ""]
    return "\n".join(out)


def write(directory, tables, gfx):
    (directory / "gfx.h").write_text(header(tables, gfx))
    (directory / "gfx.c").write_text(source(tables, gfx))
